#include <liburing.h>
#include <stddef.h>
#include <sys/socket.h>

extern const int record_send_flags;

void prepare_record_pair(struct io_uring_sqe *first,
                         struct io_uring_sqe *second,
                         int socket_fd,
                         const void *record_a,
                         const void *record_b) {
    io_uring_prep_send_zc(first, socket_fd, record_a, 8192,
                         record_send_flags, IORING_SEND_ZC_REPORT_USAGE);
    io_uring_sqe_set_data64(first, 101);
    first->flags |= IOSQE_IO_LINK;
    io_uring_prep_send(second, socket_fd, record_b, 4096, 0);
    io_uring_sqe_set_data64(second, 102);
}

